// ─── LOGIN ────────────────────────────────────────────────────────────────────
const Login = ({users,onLogin,t,lang,setLang}) => {
  const [u,sU]=useState(""); const [p,sP]=useState(""); const [err,sE]=useState(""); const [showP,setShowP]=useState(false);
  const go=()=>{
    const user=users.find(us=>us.username===u&&us.password===p);
    if(!user){sE(t.invalidCreds);return;}
    if(!user.active){sE(t.accountInactive);return;}
    onLogin(user);
  };
  const handleKey=e=>{if(e.key==="Enter") go();};
  return <div style={{minHeight:"100vh",background:`linear-gradient(135deg,${C.sidebar} 0%,#1b3a5c 100%)`,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"system-ui,sans-serif"}}>
    <div style={{background:"#fff",borderRadius:18,padding:48,width:400,boxShadow:"0 24px 80px rgba(0,0,0,0.35)"}}>
      <div style={{textAlign:"center",marginBottom:32}}>
        <div style={{width:60,height:60,background:C.accent,borderRadius:18,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 16px",fontSize:28,fontWeight:900,color:"#fff"}}>✦</div>
        <div style={{fontSize:24,fontWeight:800,color:C.text}}>{t.appName}</div>
        <div style={{fontSize:13,color:C.muted,marginTop:4}}>{t.loginTitle}</div>
      </div>

      <div style={{marginBottom:14}}>
        <label style={{display:"block",fontSize:11,fontWeight:600,color:C.muted,marginBottom:5,textTransform:"uppercase",letterSpacing:"0.05em"}}>{t.username}</label>
        <input value={u} onChange={e=>{sU(e.target.value);sE("");}} onKeyDown={handleKey} placeholder="username"
          style={{width:"100%",padding:"9px 12px",border:`1px solid ${err?C.err:C.border}`,borderRadius:8,fontSize:13,outline:"none",boxSizing:"border-box",color:C.text,fontFamily:"inherit"}}/>
      </div>

      <div style={{marginBottom:14}}>
        <label style={{display:"block",fontSize:11,fontWeight:600,color:C.muted,marginBottom:5,textTransform:"uppercase",letterSpacing:"0.05em"}}>{t.password}</label>
        <div style={{position:"relative"}}>
          <input type={showP?"text":"password"} value={p} onChange={e=>{sP(e.target.value);sE("");}} onKeyDown={handleKey} placeholder="••••••••"
            style={{width:"100%",padding:"9px 40px 9px 12px",border:`1px solid ${err?C.err:C.border}`,borderRadius:8,fontSize:13,outline:"none",boxSizing:"border-box",color:C.text,fontFamily:"inherit"}}/>
          <button type="button" onClick={()=>setShowP(!showP)} style={{position:"absolute",right:10,top:"50%",transform:"translateY(-50%)",background:"transparent",border:"none",cursor:"pointer",fontSize:15,color:C.muted,padding:0}}>
            {showP?"🙈":"👁"}
          </button>
        </div>
      </div>

      {err&&<div style={{background:C.errBg,color:C.err,fontSize:12,padding:"8px 12px",borderRadius:8,marginBottom:12,fontWeight:600}}>{err}</div>}

      <Btn onClick={go} style={{width:"100%",marginBottom:16}}>{t.signIn}</Btn>

      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <div style={{fontSize:11,color:C.muted,background:C.bg,padding:"6px 10px",borderRadius:8,flex:1,marginRight:8}}>{t.hint}</div>
        <button onClick={()=>setLang(lang==="en"?"ar":"en")} style={{padding:"6px 12px",border:`1px solid ${C.border}`,borderRadius:8,fontSize:11,cursor:"pointer",background:"transparent",color:C.muted,fontWeight:600,whiteSpace:"nowrap"}}>
          {lang==="en"?"عربي":"English"}
        </button>
      </div>
    </div>
  </div>;
};

