const Sidebar = ({mod,setMod,t,invoices,currentUser,stock,announcements,unreadAnn,pendingApprovals}) => {
  const unpaid=invoices.filter(i=>i.status==="Unpaid"||i.status==="Partially Paid").length;
  const lowStock=stock.filter(s=>s.qty<=s.reorderLevel).length;

  const visible=NAV.filter(({k})=>{
    if(k==="dashboard")     return true;
    if(k==="announcements") return true;
    if(k==="recurring")     return true;
    if(k==="approvals")     return true;
    if(k==="auditLog")      return currentUser.role==="Admin" || currentUser.role==="Manager";
    if(k==="settings")      return currentUser.role==="Admin";
    return (currentUser.permissions?.[k]||"none")!=="none";
  });

  let lastSection=null;
  return <div style={{width:210,background:C.sidebar,display:"flex",flexDirection:"column",flexShrink:0,overflowY:"auto"}}>
    <div style={{padding:"20px 18px 16px",borderBottom:"1px solid rgba(255,255,255,0.08)"}}>
      <div style={{fontSize:15,fontWeight:800,color:C.accent}}>{t.appName}</div>
      <div style={{fontSize:10,color:"rgba(255,255,255,0.3)",marginTop:1,textTransform:"uppercase",letterSpacing:"0.06em"}}>{t.tagline}</div>
    </div>
    <nav style={{padding:"10px 8px",flex:1}}>
      {visible.map(({k,ico,section})=>{
        const showSection=section&&section!==lastSection; lastSection=section||lastSection;
        const active=mod===k;
        return <div key={k}>
          {showSection&&<div style={{fontSize:9,color:"rgba(255,255,255,0.25)",fontWeight:700,textTransform:"uppercase",letterSpacing:"0.1em",padding:"12px 10px 4px"}}>{section}</div>}
          <div onClick={()=>setMod(k)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"7px 10px",borderRadius:8,marginBottom:1,cursor:"pointer",background:active?C.accentLight:"transparent",color:active?C.accent:"rgba(255,255,255,0.55)",fontSize:12,fontWeight:active?700:400,transition:"all 0.12s"}}
            onMouseEnter={e=>!active&&(e.currentTarget.style.background=C.sidHover)} onMouseLeave={e=>!active&&(e.currentTarget.style.background="transparent")}>
            <span style={{display:"flex",alignItems:"center",gap:8}}><span style={{fontSize:13}}>{ico}</span>{t[k]||k}</span>
            <span style={{display:"flex",gap:4}}>
              {k==="invoices"&&unpaid>0&&<span style={{background:C.err,color:"#fff",borderRadius:20,padding:"0 6px",fontSize:9,fontWeight:700}}>{unpaid}</span>}
              {k==="stock"&&lowStock>0&&<span style={{background:C.warn,color:C.warnBg,borderRadius:20,padding:"0 6px",fontSize:9,fontWeight:700}}>!</span>}
              {k==="announcements"&&unreadAnn>0&&<span style={{background:"#3b82f6",color:"#fff",borderRadius:20,padding:"0 6px",fontSize:9,fontWeight:700}}>{unreadAnn}</span>}
              {k==="approvals"&&pendingApprovals>0&&<span style={{background:C.warn,color:"#fff",borderRadius:20,padding:"0 6px",fontSize:9,fontWeight:700}}>{pendingApprovals}</span>}
            </span>
          </div>
        </div>;
      })}
    </nav>
    {/* Current user card at bottom */}
    <div style={{padding:"12px 14px",borderTop:"1px solid rgba(255,255,255,0.08)",display:"flex",alignItems:"center",gap:10}}>
      <div style={{width:32,height:32,borderRadius:"50%",background:C.accent,display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,fontWeight:800,color:"#1a1200",flexShrink:0}}>
        {currentUser.name.charAt(0)}
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontSize:11,fontWeight:700,color:"rgba(255,255,255,0.85)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{currentUser.name}</div>
        <div style={{fontSize:10,color:"rgba(255,255,255,0.35)"}}>{currentUser.role}</div>
      </div>
    </div>
  </div>;
};

