// ─── CSV EXPORT (works in sandbox via data URI) ──────────────────────────────
// Show toast notification
const exportExcel = (filename, headers, rows) => {
  try {
    const data = [headers, ...rows.map(r => r.map(v => String(v == null ? "" : v)))];
    const ws = XLSX.utils.aoa_to_sheet(data);
    ws["!cols"] = headers.map(() => ({ wch: 18 }));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, filename.slice(0,31));
    XLSX.writeFile(wb, filename + ".xlsx");
    showToast("✓ " + filename + ".xlsx downloaded!");
  } catch(e) {
    console.error("Excel error:", e);
    downloadCSV(filename + ".csv", headers, rows);
  }
};

const showToast = (msg, ok=true) => {
  const el = document.createElement('div');
  el.style.cssText = `position:fixed;top:20px;right:20px;z-index:99999;background:${ok?'#c6f6d5':'#fed7d7'};color:${ok?'#276749':'#9b2c2c'};padding:14px 20px;border-radius:12px;font-weight:700;font-size:13px;font-family:system-ui;box-shadow:0 4px 24px rgba(0,0,0,0.18);max-width:340px;line-height:1.5;`;
  el.textContent = msg;
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 4000);
};

const downloadCSV = (filename, headers, rows) => {
  const esc = v => {
    const s = String(v==null?"":v);
    return (s.includes(",")||s.includes('"')||s.includes("\n")) ? `"${s.replace(/"/g,'""')}"` : s;
  };
  const csv = [headers,...rows].map(r=>r.map(esc).join(",")).join("\n");

  // Try native download first
  try {
    const blob = new Blob(["\uFEFF"+csv], {type:"text/csv;charset=utf-8;"});
    const url  = URL.createObjectURL(blob);
    const a    = Object.assign(document.createElement("a"), {href:url, download:filename});
    document.body.appendChild(a); a.click();
    setTimeout(()=>{URL.revokeObjectURL(url);a.remove();}, 500);
    showToast("✓ "+filename+" downloaded!");
    return;
  } catch(_) {}

  // Fallback: copy to clipboard
  navigator.clipboard.writeText(csv)
    .then(()  => showToast("✓ "+rows.length+" rows copied to clipboard!\nOpen Excel → Ctrl+V to paste.", true))
    .catch(()  => {
      // Last resort: show in textarea overlay
      const overlay = document.createElement('div');
      overlay.style.cssText = "position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.6);display:flex;align-items:center;justify-content:center;";
      overlay.innerHTML = `<div style="background:#fff;border-radius:14px;padding:24px;width:600px;max-width:94vw;max-height:80vh;display:flex;flex-direction:column;gap:12px;box-shadow:0 20px 60px rgba(0,0,0,0.3);">
        <div style="font-weight:700;font-size:14px;">Export: ${filename}</div>
        <div style="font-size:12px;color:#718096;">Select all (Ctrl+A) then copy (Ctrl+C), then paste into Excel</div>
        <textarea readonly style="flex:1;min-height:200px;font-family:monospace;font-size:11px;padding:10px;border:1px solid #e2e8f0;border-radius:8px;resize:vertical;">${csv}</textarea>
        <div style="display:flex;gap:8px;">
          <button onclick="this.closest('div').parentNode.parentNode.remove()" style="padding:8px 18px;background:#1e3a8a;color:#fff;border:none;border-radius:8px;cursor:pointer;font-weight:700;">Close</button>
        </div>
      </div>`;
      document.body.appendChild(overlay);
      overlay.querySelector('textarea').select();
    });
};

const exportInvoicesCSV = (invoices,clients) => downloadCSV("avera_invoices.csv",
  ["Invoice ID","Date","Client","Service","Location","Amount","Paid","Remaining","Status","Method","Notes"],
  invoices.map(i=>{const cl=clients.find(c=>c.id===i.clientId); return[i.id,i.date,cl?.name||"",i.serviceType,i.location,i.amount,i.amountPaid,i.amount-i.amountPaid,i.status,i.paymentMethod,i.notes];}));

const exportClientsCSV = clients => downloadCSV("avera_clients.csv",
  ["ID","Name","Phone","Email","Location","Joined","Notes"],
  clients.map(c=>[c.id,c.name,c.phone,c.email,c.location,c.joinDate,c.notes]));

const exportStockCSV = stock => downloadCSV("avera_stock.csv",
  ["ID","Item","Category","Qty","Reorder Level","Unit Price","Total Value","Supplier","Supplier Contact","Notes"],
  stock.map(s=>[s.id,s.item,s.category,s.qty,s.reorderLevel,s.unitPrice,(s.qty*s.unitPrice).toFixed(2),s.supplier,s.supplierContact,s.notes]));

const exportJobsCSV = (jobs,clients) => downloadCSV("avera_jobs.csv",
  ["Job ID","Client","Service","Package Details","Location","Start","End","Staff","Status","Notes"],
  jobs.map(j=>{const cl=clients.find(c=>c.id===j.clientId); return[j.id,cl?.name||"",j.serviceType,j.packageDetails,j.location,j.startDate,j.endDate,j.staffAssigned,j.paymentStatus,j.notes];}));

const exportPayrollCSV = (emp,month,year,days) => {
  const mn=["January","February","March","April","May","June","July","August","September","October","November","December"][month-1];
  downloadCSV(`avera_payroll_${emp.name.replace(/\s+/g,"_")}_${mn}_${year}.csv`,
    ["Date","Day","Status","Time In","Time Out","Hours","Extra Pay","Bonus","Pay","Notes"],
    days.map(d=>{
      const isOff=d.workStatus==="Day Off"||d.workStatus==="Holiday"||d.workStatus==="Absent";
      const hrs=(!isOff&&d.timeIn&&d.timeOut)?(()=>{const[h1,m1]=d.timeIn.split(":").map(Number);const[h2,m2]=d.timeOut.split(":").map(Number);return Math.max(0,((h2*60+m2)-(h1*60+m1))/60-(parseFloat(d.breakHrs)||0));})():0;
      const pay=hrs*emp.hourlyRate+parseFloat(d.extraPay||0);
      return[d.date,d.day,d.workStatus,d.timeIn||"",d.timeOut||"",hrs.toFixed(1),d.extraPay||0,d.bonus||0,pay.toFixed(2),d.notes||""];
    })
  );
};

