const INIT_ANNOUNCEMENTS = [
  {id:"ANN-001",title:"Welcome to Avera CleanPro!",body:"Your management system is now live. All modules are ready to use. Contact admin for any questions.",category:"News",priority:"Normal",author:"Admin User",authorRole:"Admin",date:"2026-04-20",time:"09:00",pinned:true,visibility:"all",readBy:[],createdAt:"2026-04-20"},
  {id:"ANN-002",title:"April Invoices Due",body:"Reminder: All April invoices must be settled before end of month. Clients with overdue payments will be flagged.",category:"Financial Notice",priority:"Important",author:"Admin User",authorRole:"Admin",date:"2026-04-25",time:"10:30",pinned:false,visibility:"all",readBy:[],createdAt:"2026-04-25"},
  {id:"ANN-003",title:"New Staff Onboarding",body:"Joujou has joined the team this month. Please welcome her and ensure she has everything she needs.",category:"Update",priority:"Normal",author:"Amr Manager",authorRole:"Manager",date:"2026-04-27",time:"08:00",pinned:false,visibility:"all",readBy:[],createdAt:"2026-04-27"},
];

// ─── ANNOUNCEMENTS MODULE ─────────────────────────────────────────────────────
const ANN_CATEGORIES = ["News","Alert","Update","Financial Notice"];
const ANN_PRIORITIES = ["Normal","Important","Urgent"];

const AnnouncementsModule = ({announcements,setAnnouncements,currentUser,t,addAudit}) => {
  const [drawer,setDrawer]=useState(false);
  const [editing,setEditing]=useState(null);
  const [form,setForm]=useState({});
  const [expanded,setExpanded]=useState({});
  const [filt,setFilt]=useState("All");
  const [delId,setDelId]=useState(null);
  const fc=(k,v)=>setForm(f=>({...f,[k]:v}));

  const canPost = currentUser.role==="Admin"||(currentUser.role==="Manager"&&currentUser.permissions?.announcements!=="none");
  const sorted = [...announcements].sort((a,b)=>{
    if(a.pinned&&!b.pinned) return -1;
    if(!a.pinned&&b.pinned) return 1;
    return (b.date+b.time).localeCompare(a.date+a.time);
  });
  const filtered = sorted.filter(a=>filt==="All"||(filt==="Pinned"&&a.pinned)||a.category===filt||a.priority===filt);
  const unread = announcements.filter(a=>!a.readBy?.includes(currentUser.id));

  const blank={id:"",title:"",body:"",category:"News",priority:"Normal",author:currentUser.name,authorRole:currentUser.role,date:today(),time:new Date().toTimeString().slice(0,5),pinned:false,visibility:"all",readBy:[],createdAt:today()};

  const save=()=>{
    if(!form.title?.trim()||!form.body?.trim()) return;
    if(editing){
      setAnnouncements(as=>as.map(a=>a.id===editing?{...form}:a));
      addAudit('Updated','Announcements',editing,form.title,'Announcement updated');
    } else {
      const id="ANN-"+String(Math.max(0,...announcements.map(a=>parseInt(a.id.replace(/\D/g,""))||0))+1).padStart(3,"0");
      setAnnouncements(as=>[{...form,id,readBy:[]},...as]);
      addAudit('Created','Announcements',id,form.title,'Priority: '+form.priority+' | Category: '+form.category);
    }
    setDrawer(false);setEditing(null);
  };

  const del=()=>{setAnnouncements(as=>as.filter(a=>a.id!==delId));setDelId(null);};

  const markRead=(id)=>setAnnouncements(as=>as.map(a=>a.id===id?{...a,readBy:[...(a.readBy||[]),currentUser.id]}:a));
  const markAllRead=()=>setAnnouncements(as=>as.map(a=>({...a,readBy:[...(a.readBy||[]),currentUser.id]})));
  const togglePin=(id)=>setAnnouncements(as=>as.map(a=>a.id===id?{...a,pinned:!a.pinned}:a));

  const openEdit=(ann)=>{setForm({...ann});setEditing(ann.id);setDrawer(true);};
  const openNew=()=>{setForm({...blank});setEditing(null);setDrawer(true);};

  const isRead=(ann)=>ann.readBy?.includes(currentUser.id);
  const canEdit=(ann)=>currentUser.role==="Admin"||(currentUser.role==="Manager"&&ann.author===currentUser.name);

  return (
    <div>
      {/* Header row */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16,flexWrap:"wrap",gap:10}}>
        <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
          <FilterBar active={filt} onChange={setFilt} options={["All","Pinned","Urgent","Important","News","Alert","Update","Financial Notice"]}/>
        </div>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          {unread.length>0&&<button onClick={markAllRead} style={{padding:"5px 14px",border:`1px solid ${C.border}`,borderRadius:8,fontSize:12,cursor:"pointer",background:"transparent",color:C.muted}}>
            ✓ Mark all read ({unread.length})
          </button>}
          {canPost&&<Btn onClick={openNew}>+ New Announcement</Btn>}
        </div>
      </div>

      {/* Stats */}
      <div style={{display:"flex",gap:10,marginBottom:16,flexWrap:"wrap"}}>
        <StatCard label="Total" value={announcements.length}/>
        <StatCard label="Unread" value={unread.length} accent={unread.length>0?C.err:C.ok}/>
        <StatCard label="Pinned" value={announcements.filter(a=>a.pinned).length} accent={C.accent}/>
        <StatCard label="Urgent" value={announcements.filter(a=>a.priority==="Urgent").length} accent={C.err}/>
      </div>

      {/* Feed */}
      {filtered.length===0&&<div style={{background:"#fff",borderRadius:12,border:`1px solid ${C.border}`,padding:48,textAlign:"center",color:C.muted,fontSize:13}}>No announcements found.</div>}
      <div style={{display:"flex",flexDirection:"column",gap:12}}>
        {filtered.map(ann=>{
          const read=isRead(ann);
          const exp=expanded[ann.id];
          const urgent=ann.priority==="Urgent";
          return (
            <div key={ann.id} style={{background:"#fff",borderRadius:12,border:`2px solid ${ann.pinned?C.accent:urgent?"#feb2b2":read?C.border:"#bfdbfe"}`,boxShadow:"0 1px 4px rgba(0,0,0,0.05)",overflow:"hidden",transition:"border-color 0.2s"}}>
              {/* Top accent bar for urgent */}
              {urgent&&<div style={{height:3,background:"linear-gradient(90deg,#e53e3e,#feb2b2)"}}/>}
              {ann.pinned&&<div style={{height:3,background:`linear-gradient(90deg,${C.accent},rgba(212,168,67,0.3))`}}/>}

              <div style={{padding:"16px 20px"}}>
                {/* Row 1: badges + meta */}
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:8,marginBottom:8}}>
                  <div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>
                    {ann.pinned&&<span style={{fontSize:13}}>📌</span>}
                    {!read&&<span style={{width:8,height:8,borderRadius:"50%",background:"#3b82f6",display:"inline-block",flexShrink:0}}/>}
                    <CatBadge category={ann.category}/>
                    <AnnBadge priority={ann.priority}/>
                  </div>
                  <div style={{fontSize:11,color:C.muted,display:"flex",gap:12,alignItems:"center"}}>
                    <span>👤 {ann.author}</span>
                    <span>📅 {ann.date} {ann.time}</span>
                    {ann.readBy?.length>0&&<span style={{color:C.ok}}>👁 {ann.readBy.length} read</span>}
                  </div>
                </div>

                {/* Title */}
                <div style={{fontSize:15,fontWeight:800,color:C.text,marginBottom:6}}>{ann.title}</div>

                {/* Body — expandable */}
                <div style={{fontSize:13,color:C.muted,lineHeight:1.6,marginBottom:10}}>
                  {exp||ann.body.length<=140
                    ? ann.body
                    : ann.body.slice(0,140)+"…"}
                </div>
                {ann.body.length>140&&(
                  <button onClick={()=>setExpanded(e=>({...e,[ann.id]:!e[ann.id]}))}
                    style={{background:"transparent",border:"none",color:C.accent,fontSize:12,fontWeight:600,cursor:"pointer",padding:0,marginBottom:8}}>
                    {exp?"▲ Show less":"▼ Read more"}
                  </button>
                )}

                {/* Actions */}
                <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",paddingTop:8,borderTop:`1px solid ${C.border}`}}>
                  {!read&&<Btn onClick={()=>markRead(ann.id)} variant="ghost" sm>✓ Mark as read</Btn>}
                  {canEdit(ann)&&<>
                    {currentUser.role==="Admin"&&<Btn onClick={()=>togglePin(ann.id)} variant="secondary" sm>{ann.pinned?"📌 Unpin":"📌 Pin"}</Btn>}
                    <Btn onClick={()=>openEdit(ann)} variant="secondary" sm>Edit</Btn>
                    <Btn onClick={()=>setDelId(ann.id)} variant="danger" sm>✕</Btn>
                  </>}
                  {read&&<span style={{fontSize:11,color:C.ok,marginLeft:"auto"}}>✓ Read</span>}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Create/Edit Drawer */}
      <Drawer open={drawer} onClose={()=>{setDrawer(false);setEditing(null);}} title={editing?"Edit Announcement":"New Announcement"} width={500}>
        <Inp label="Title *" value={form.title} onChange={v=>fc("title",v)}/>
        <div style={{marginBottom:14}}>
          <label style={{display:"block",fontSize:11,fontWeight:600,color:C.muted,marginBottom:5,textTransform:"uppercase",letterSpacing:"0.05em"}}>Content *</label>
          <textarea value={form.body||""} onChange={e=>fc("body",e.target.value)} rows={6}
            placeholder="Write your announcement content here…"
            style={{width:"100%",padding:"9px 12px",border:`1px solid ${C.border}`,borderRadius:8,fontSize:13,outline:"none",boxSizing:"border-box",color:C.text,background:"#fff",fontFamily:"inherit",resize:"vertical",lineHeight:1.6}}/>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          <Sel label="Category" value={form.category} onChange={v=>fc("category",v)} options={ANN_CATEGORIES}/>
          <Sel label="Priority" value={form.priority} onChange={v=>fc("priority",v)} options={ANN_PRIORITIES}/>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          <Inp label="Date" value={form.date} onChange={v=>fc("date",v)} type="date"/>
          <Inp label="Time" value={form.time} onChange={v=>fc("time",v)} type="time"/>
        </div>
        <Sel label="Visible To" value={form.visibility||"all"} onChange={v=>fc("visibility",v)} options={[{value:"all",label:"All Users"},{value:"Admin",label:"Admin Only"},{value:"Manager",label:"Manager & Admin"}]}/>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:16,padding:"10px 14px",background:C.bg,borderRadius:8}}>
          <input type="checkbox" id="pinned" checked={!!form.pinned} onChange={e=>fc("pinned",e.target.checked)} style={{cursor:"pointer",width:16,height:16}}/>
          <label htmlFor="pinned" style={{fontSize:13,fontWeight:600,cursor:"pointer",color:C.text}}>📌 Pin this announcement to top</label>
        </div>
        {/* Preview */}
        {form.title&&<div style={{marginBottom:16,padding:"12px 16px",background:"#f8faff",borderRadius:10,border:`1px solid #bfdbfe`}}>
          <div style={{fontSize:10,color:C.muted,fontWeight:700,textTransform:"uppercase",marginBottom:6}}>Preview</div>
          <div style={{display:"flex",gap:6,marginBottom:6}}><CatBadge category={form.category}/><AnnBadge priority={form.priority}/></div>
          <div style={{fontWeight:700,fontSize:14,marginBottom:4}}>{form.title}</div>
          <div style={{fontSize:12,color:C.muted,lineHeight:1.5}}>{(form.body||"").slice(0,100)}{form.body?.length>100?"…":""}</div>
        </div>}
        <div style={{display:"flex",gap:8}}><Btn onClick={save}>Publish</Btn><Btn onClick={()=>{setDrawer(false);setEditing(null);}} variant="secondary">Cancel</Btn></div>
      </Drawer>

      <ConfirmModal open={!!delId} onClose={()=>setDelId(null)} onConfirm={del} message="Delete this announcement?"/>
    </div>
  );
};

// ─── ANNOUNCEMENT BELL (for header/sidebar) ───────────────────────────────────
const AnnouncementBell = ({announcements,currentUser,onClick}) => {
  const unread=announcements.filter(a=>!a.readBy?.includes(currentUser.id)).length;
  return (
    <div onClick={onClick} style={{position:"relative",cursor:"pointer",width:32,height:32,display:"flex",alignItems:"center",justifyContent:"center"}}>
      <span style={{fontSize:18}}>🔔</span>
      {unread>0&&<span style={{position:"absolute",top:-2,right:-2,background:C.err,color:"#fff",borderRadius:"50%",width:16,height:16,fontSize:9,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center",lineHeight:1}}>{unread>9?"9+":unread}</span>}
    </div>
  );
};

// ─── APP ROOT ─────────────────────────────────────────────────────────────────
export default function App() {
  const [currentUser,setCurrentUser]=useState(null);
  const [lang,setLang]=useState("en");
  const [mod,setMod]=useState("dashboard");
  const [clients,setClients]=useState(INIT_CLIENTS);
  const [jobs,setJobs]=useState(INIT_JOBS);
  const [invoices,setInvoices]=useState(INIT_INVOICES);
  const [quotations,setQuotations]=useState(INIT_QUOTATIONS);
  const [employees,setEmployees]=useState(INIT_EMPLOYEES);
  const [services,setServices]=useState(INIT_SERVICES);
  const [stock,setStock]=useState(INIT_STOCK);
  const [stockMovements,setStockMovements]=useState([]);
  const [workTracker,setWorkTracker]=useState(INIT_WORK_TRACKER);
  const [users,setUsers]=useState(INIT_USERS);
  const [tasks,setTasks]=useState(INIT_TASKS);
  const [settings,setSettings]=useState(INIT_SETTINGS);
  const [announcements,setAnnouncements]=useState(INIT_ANNOUNCEMENTS);
  const [recurringTemplates,setRecurringTemplates]=useState(INIT_RECURRING);
  const [approvals,setApprovals]=useState([]);
  const [auditLog,setAuditLog]=useState([]);
  const [printJob,setPrintJob]=useState(null);
  const [reportModal,setReportModal]=useState(null);

  const t=TR[lang]; const isAr=lang==="ar";

  // ── Audit logger ─────────────────────────────────────────────────────────────
  const addAudit = useCallback((action,module,recordId,recordLabel,details="",before=null,after=null) => {
    const entry = {
      id: `AUD-${Date.now()}`,
      timestamp: new Date().toISOString(),
      date: new Date().toISOString().slice(0,10),
      time: new Date().toTimeString().slice(0,8),
      user: currentUser?.name || "System",
      userRole: currentUser?.role || "",
      action,      // "Created" | "Updated" | "Deleted" | "Status Changed" | "Login" | "Password Changed"
      module,      // "Clients" | "Invoices" | "Jobs" | "Stock" | etc.
      recordId,
      recordLabel,
      details,
      before: before ? JSON.stringify(before) : null,
      after:  after  ? JSON.stringify(after)  : null,
    };
    setAuditLog(prev => [entry, ...prev].slice(0, 2000)); // keep last 2000
  }, [currentUser]);

  const handleLogin = (user) => { setCurrentUser(user); setAuditLog(prev=>[{id:`AUD-${Date.now()}`,timestamp:new Date().toISOString(),date:new Date().toISOString().slice(0,10),time:new Date().toTimeString().slice(0,8),user:user.name,userRole:user.role,action:'Login',module:'System',recordId:'',recordLabel:user.name,details:'User logged in',before:null,after:null},...prev].slice(0,2000)); };
  if(!currentUser) return <Login users={users} onLogin={handleLogin} t={t} lang={lang} setLang={setLang}/>;

  // Unread count for bell
  const unreadAnn=announcements.filter(a=>!a.readBy?.includes(currentUser.id)).length;

  return (
    <>
    <PrintModal job={printJob} onClose={()=>setPrintJob(null)} clients={clients} settings={settings}/>
    <ReportModal report={reportModal} onClose={()=>setReportModal(null)} onPrint={setPrintJob} settings={settings}/>
    <div style={{display:"flex",height:"100vh",fontFamily:"-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif",direction:isAr?"rtl":"ltr",background:C.bg,overflow:"hidden"}}>
      <Sidebar mod={mod} setMod={setMod} t={t} invoices={invoices} currentUser={currentUser} stock={stock} announcements={announcements} unreadAnn={unreadAnn} pendingApprovals={approvals.filter(a=>a.status==="Pending").length}/>
      <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden",minWidth:0}}>
        {/* Header with bell */}
        <div style={{height:52,background:"#fff",borderBottom:`1px solid ${C.border}`,display:"flex",alignItems:"center",justifyContent:"space-between",padding:"0 24px",flexShrink:0}}>
          <div style={{fontSize:15,fontWeight:700,color:C.text}}>{t[mod]||mod}</div>
          <div style={{display:"flex",alignItems:"center",gap:12}}>
            <AnnouncementBell announcements={announcements} currentUser={currentUser} onClick={()=>setMod("announcements")}/>
            <button onClick={()=>setLang(lang==="en"?"ar":"en")} style={{padding:"4px 10px",border:`1px solid ${C.border}`,borderRadius:7,fontSize:11,cursor:"pointer",background:"transparent",color:C.muted,fontWeight:600}}>{lang==="en"?"عربي":"English"}</button>
            <div style={{textAlign:"right"}}>
              <div style={{fontSize:12,fontWeight:700,color:C.text}}>{currentUser.name}</div>
              <div style={{fontSize:10,color:C.muted}}>{currentUser.role}</div>
            </div>
            <div style={{width:32,height:32,borderRadius:"50%",background:C.accent,display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,fontWeight:800,color:"#1a1200"}}>{currentUser.name.charAt(0)}</div>
            <button onClick={()=>{setCurrentUser(null);setMod("dashboard");}} style={{padding:"4px 10px",border:`1px solid ${C.border}`,borderRadius:7,fontSize:11,cursor:"pointer",background:"transparent",color:C.muted}}>{t.logout}</button>
          </div>
        </div>
        <main style={{flex:1,overflow:"auto",padding:20}}>
          {mod==="dashboard"      && <Dashboard t={t} clients={clients} jobs={jobs} invoices={invoices} setMod={setMod} currentUser={currentUser} settings={settings} announcements={announcements} employees={employees} tasks={tasks} stock={stock}/>}
          {mod==="clients"        && <ClientsModule t={t} clients={clients} setClients={setClients} jobs={jobs} invoices={invoices} settings={settings} onPrint={setPrintJob} onReport={setReportModal} addAudit={addAudit}/>}
          {mod==="jobs"           && <JobsModule t={t} jobs={jobs} setJobs={setJobs} clients={clients} settings={settings} onPrint={setPrintJob} onReport={setReportModal} addAudit={addAudit}/>}
          {mod==="invoices"       && <InvoicesModule t={t} invoices={invoices} setInvoices={setInvoices} clients={clients} jobs={jobs} settings={settings} onPrint={setPrintJob} onReport={setReportModal} addAudit={addAudit} approvals={approvals} setApprovals={setApprovals} currentUser={currentUser}/>}
          {mod==="quotations"     && <QuotationsModule t={t} quotations={quotations} setQuotations={setQuotations} clients={clients} invoices={invoices} setInvoices={setInvoices} settings={settings} onPrint={setPrintJob} onReport={setReportModal} addAudit={addAudit} approvals={approvals} setApprovals={setApprovals} currentUser={currentUser}/>}
          {mod==="employees"      && <EmployeesModule t={t} employees={employees} setEmployees={setEmployees} addAudit={addAudit}/>}
          {mod==="payroll"        && <PayrollModule employees={employees} settings={settings} onPrint={setPrintJob}/>}
          {mod==="workTracker"    && <WorkTrackerModule clients={clients} jobs={jobs} workTracker={workTracker} setWorkTracker={setWorkTracker}/>}
          {mod==="services"       && <ServicesModule services={services} setServices={setServices}/>}
          {mod==="stock"          && <StockModule stock={stock} setStock={setStock} stockMovements={stockMovements} setStockMovements={setStockMovements} currentUser={currentUser} settings={settings} onPrint={setPrintJob} onReport={setReportModal} addAudit={addAudit}/>}
          {mod==="users"          && <UsersModule users={users} setUsers={setUsers} currentUser={currentUser} addAudit={addAudit}/>}
          {mod==="tasks"          && <TasksModule tasks={tasks} setTasks={setTasks} users={users} addAudit={addAudit}/>}
          {mod==="recurring"       && <RecurringModule recurringTemplates={recurringTemplates} setRecurringTemplates={setRecurringTemplates} clients={clients} invoices={invoices} setInvoices={setInvoices} settings={settings} addAudit={addAudit} currentUser={currentUser}/>}
          {mod==="approvals"       && <ApprovalsModule approvals={approvals} setApprovals={setApprovals} invoices={invoices} setInvoices={setInvoices} quotations={quotations} setQuotations={setQuotations} clients={clients} currentUser={currentUser} addAudit={addAudit}/>}
          {mod==="auditLog"        && <AuditLogModule auditLog={auditLog} currentUser={currentUser} onReport={setReportModal}/>}
          {mod==="announcements"  && <AnnouncementsModule announcements={announcements} setAnnouncements={setAnnouncements} currentUser={currentUser} t={t} addAudit={addAudit}/>}
          {mod==="settings"       && currentUser.role==="Admin" && <SettingsModule settings={settings} setSettings={setSettings} currentUser={currentUser}/>}
        </main>
      </div>
    </div>
    </>
  );
}

// ─── AUDIT LOG MODULE ─────────────────────────────────────────────────────────
const ACTION_COLORS = {
  'Created':        {bg:'#c6f6d5',col:'#276749'},
  'Updated':        {bg:'#dbeafe',col:'#1e3a8a'},
  'Deleted':        {bg:'#fed7d7',col:'#9b2c2c'},
  'Status Changed': {bg:'#fefcbf',col:'#744210'},
  'Login':          {bg:'#e9d8fd',col:'#553c9a'},
  'Password Changed':{bg:'#fecaca',col:'#991b1b'},
  'Stock In':       {bg:'#c6f6d5',col:'#276749'},
  'Stock Out':      {bg:'#fed7d7',col:'#9b2c2c'},
};

const AuditLogModule = ({auditLog, currentUser, onReport}) => {
  const [q, setQ]           = useState('');
  const [modFilt, setMF]    = useState('All');
  const [actFilt, setAF]    = useState('All');
  const [from, setFrom]     = useState('');
  const [to, setTo]         = useState('');
  const [expanded, setExp]  = useState(null);

  const modules = ['All', ...new Set(auditLog.map(a => a.module))];
  const actions = ['All', 'Created', 'Updated', 'Deleted', 'Status Changed', 'Login', 'Password Changed', 'Stock In', 'Stock Out'];

  const filtered = auditLog.filter(a => {
    if(modFilt !== 'All' && a.module !== modFilt) return false;
    if(actFilt !== 'All' && a.action !== actFilt) return false;
    if(from && a.date < from) return false;
    if(to   && a.date > to)   return false;
    if(q && !(a.user+a.module+a.recordLabel+a.details+a.action).toLowerCase().includes(q.toLowerCase())) return false;
    return true;
  });

  // Stats
  const today_str = new Date().toISOString().slice(0,10);
  const todayCount   = auditLog.filter(a => a.date === today_str).length;
  const deletedCount = auditLog.filter(a => a.action === 'Deleted').length;
  const logins       = auditLog.filter(a => a.action === 'Login').length;

  const exportAudit = () => {
    downloadCSV('audit_log.csv',
      ['Timestamp','User','Role','Action','Module','Record','Details'],
      filtered.map(a => [a.timestamp, a.user, a.userRole, a.action, a.module, a.recordLabel, a.details])
    );
  };

  return (
    <div>
      {/* Stats */}
      <div style={{display:'flex',gap:10,marginBottom:14,flexWrap:'wrap'}}>
        <StatCard label="Total Events"   value={auditLog.length}/>
        <StatCard label="Today"          value={todayCount}   accent={C.info}/>
        <StatCard label="Deletions"      value={deletedCount} accent={deletedCount>0?C.err:C.ok}/>
        <StatCard label="Logins"         value={logins}       accent={C.purple}/>
      </div>

      {/* Filters */}
      <div style={{background:'#fff',borderRadius:12,border:`1px solid ${C.border}`,padding:'14px 18px',marginBottom:14}}>
        <div style={{display:'flex',gap:12,flexWrap:'wrap',alignItems:'flex-end'}}>
          <div style={{flex:1,minWidth:200}}>
            <input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search user, module, record…"
              style={{width:'100%',padding:'7px 12px',border:`1px solid ${C.border}`,borderRadius:8,fontSize:13,outline:'none',color:C.text,background:'#fff',fontFamily:'inherit'}}/>
          </div>
          <div>
            <label style={{display:'block',fontSize:10,fontWeight:700,color:C.muted,marginBottom:4,textTransform:'uppercase',letterSpacing:'0.05em'}}>Module</label>
            <select value={modFilt} onChange={e=>setMF(e.target.value)}
              style={{padding:'7px 12px',border:`1px solid ${C.border}`,borderRadius:8,fontSize:12,outline:'none',color:C.text,background:'#fff',fontFamily:'inherit'}}>
              {modules.map(m=><option key={m}>{m}</option>)}
            </select>
          </div>
          <div>
            <label style={{display:'block',fontSize:10,fontWeight:700,color:C.muted,marginBottom:4,textTransform:'uppercase',letterSpacing:'0.05em'}}>Action</label>
            <select value={actFilt} onChange={e=>setAF(e.target.value)}
              style={{padding:'7px 12px',border:`1px solid ${C.border}`,borderRadius:8,fontSize:12,outline:'none',color:C.text,background:'#fff',fontFamily:'inherit'}}>
              {actions.map(a=><option key={a}>{a}</option>)}
            </select>
          </div>
          <div>
            <label style={{display:'block',fontSize:10,fontWeight:700,color:C.muted,marginBottom:4,textTransform:'uppercase',letterSpacing:'0.05em'}}>From</label>
            <input type="date" value={from} onChange={e=>setFrom(e.target.value)}
              style={{padding:'7px 10px',border:`1px solid ${C.border}`,borderRadius:8,fontSize:12,outline:'none',color:C.text,background:'#fff',fontFamily:'inherit'}}/>
          </div>
          <div>
            <label style={{display:'block',fontSize:10,fontWeight:700,color:C.muted,marginBottom:4,textTransform:'uppercase',letterSpacing:'0.05em'}}>To</label>
            <input type="date" value={to} onChange={e=>setTo(e.target.value)}
              style={{padding:'7px 10px',border:`1px solid ${C.border}`,borderRadius:8,fontSize:12,outline:'none',color:C.text,background:'#fff',fontFamily:'inherit'}}/>
          </div>
          {(from||to||q||modFilt!=='All'||actFilt!=='All') &&
            <Btn onClick={()=>{setQ('');setMF('All');setAF('All');setFrom('');setTo('');}} variant="secondary" sm>✕ Clear</Btn>}
          <div style={{marginLeft:'auto',display:'flex',gap:8}}>
            <span style={{fontSize:12,color:C.muted,display:'flex',alignItems:'center'}}>
              <strong style={{color:C.text,marginRight:4}}>{filtered.length}</strong> of {auditLog.length} events
            </span>
            <Btn onClick={exportAudit} variant="secondary" sm>📊 Export CSV</Btn>
          </div>
        </div>
      </div>

      {/* Log table */}
      {auditLog.length === 0
        ? <div style={{background:'#fff',borderRadius:12,border:`1px solid ${C.border}`,padding:'60px 0',textAlign:'center',color:C.muted}}>
            <div style={{fontSize:32,marginBottom:12}}>🔍</div>
            <div style={{fontSize:14,fontWeight:700,marginBottom:6}}>No activity yet</div>
            <div style={{fontSize:12}}>Actions you take in the system will appear here.</div>
          </div>
        : <div style={{background:'#fff',borderRadius:12,border:`1px solid ${C.border}`,overflow:'auto',boxShadow:'0 1px 4px rgba(0,0,0,0.05)'}}>
            <table style={{width:'100%',borderCollapse:'collapse',minWidth:750}}>
              <thead>
                <tr style={{background:C.bg}}>
                  {['Date','Time','User','Action','Module','Record / Details',''].map((h,i)=>(
                    <th key={i} style={{padding:'8px 12px',fontSize:10,fontWeight:700,color:C.muted,textAlign:'left',borderBottom:`1px solid ${C.border}`,textTransform:'uppercase',letterSpacing:'0.05em',whiteSpace:'nowrap'}}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtered.length===0
                  ? <tr><td colSpan={7} style={{textAlign:'center',padding:32,color:C.muted,fontSize:13}}>No records match the filters.</td></tr>
                  : filtered.slice(0,200).map((a,i) => {
                    const ac = ACTION_COLORS[a.action] || {bg:'#e2e8f0',col:'#4a5568'};
                    const isExp = expanded === a.id;
                    const hasDiff = a.before || a.after;
                    return (
                      <tr key={a.id} style={{borderBottom:`1px solid ${C.border}`,background:i%2===0?'#fff':'#fafafa',cursor:hasDiff?'pointer':'default'}}
                        onClick={()=>hasDiff&&setExp(isExp?null:a.id)}>
                        <td style={{padding:'8px 12px',fontSize:12,color:C.muted,whiteSpace:'nowrap'}}>{a.date}</td>
                        <td style={{padding:'8px 12px',fontSize:11,color:C.muted,fontFamily:'monospace',whiteSpace:'nowrap'}}>{a.time}</td>
                        <td style={{padding:'8px 12px'}}>
                          <div style={{fontSize:12,fontWeight:700,color:C.text}}>{a.user}</div>
                          <div style={{fontSize:10,color:C.muted}}>{a.userRole}</div>
                        </td>
                        <td style={{padding:'8px 12px'}}>
                          <span style={{background:ac.bg,color:ac.col,padding:'3px 10px',borderRadius:20,fontSize:10,fontWeight:700,whiteSpace:'nowrap'}}>{a.action}</span>
                        </td>
                        <td style={{padding:'8px 12px'}}>
                          <span style={{background:C.infoBg,color:C.info,padding:'2px 8px',borderRadius:10,fontSize:10,fontWeight:600}}>{a.module}</span>
                        </td>
                        <td style={{padding:'8px 12px',maxWidth:280}}>
                          <div style={{fontSize:12,fontWeight:600,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{a.recordLabel}</div>
                          <div style={{fontSize:11,color:C.muted}}>{a.details}</div>
                          {isExp && hasDiff && (
                            <div style={{marginTop:8,display:'grid',gridTemplateColumns:'1fr 1fr',gap:8}}>
                              {a.before && <div style={{background:'#fff5f5',borderRadius:6,padding:'6px 10px',fontSize:10,fontFamily:'monospace',color:C.err,border:`1px solid #fed7d7`}}>
                                <div style={{fontWeight:700,marginBottom:2,fontFamily:'system-ui'}}>Before</div>
                                {JSON.stringify(JSON.parse(a.before),null,1)}
                              </div>}
                              {a.after && <div style={{background:'#f0fff4',borderRadius:6,padding:'6px 10px',fontSize:10,fontFamily:'monospace',color:C.ok,border:`1px solid #c6f6d5`}}>
                                <div style={{fontWeight:700,marginBottom:2,fontFamily:'system-ui'}}>After</div>
                                {JSON.stringify(JSON.parse(a.after),null,1)}
                              </div>}
                            </div>
                          )}
                        </td>
                        <td style={{padding:'8px 12px'}}>
                          {hasDiff && <span style={{fontSize:10,color:C.muted}}>{isExp?'▲':'▼'}</span>}
                        </td>
                      </tr>
                    );
                  })}
                {filtered.length>200 && <tr><td colSpan={7} style={{padding:'10px 12px',fontSize:11,color:C.muted,textAlign:'center'}}>Showing first 200 of {filtered.length} — use Export CSV for full list</td></tr>}
              </tbody>
            </table>
          </div>
      }
    </div>
  );
};

// ─── INIT RECURRING DATA ─────────────────────────────────────────────────────
const INIT_RECURRING = [
  {id:"REC-001",clientId:"CLT-001",jobId:"CL-00041",serviceType:"Monthly Package",location:"Dam w Farez",amount:165,description:"3 visits/week 2hrs — Kinan Jomaa",frequency:"monthly",dayOfMonth:1,active:true,lastGenerated:"2026-04-02",staffAssigned:"Joujou",notes:""},
  {id:"REC-002",clientId:"CLT-002",jobId:"CL-00042",serviceType:"Monthly Package",location:"AlMaarad",amount:200,description:"4 visits/week 2hrs — RemotelyX",frequency:"monthly",dayOfMonth:1,active:true,lastGenerated:"2026-04-02",staffAssigned:"Cherine",notes:""},
];

// ─── RECURRING INVOICES MODULE (5C) ──────────────────────────────────────────
const RecurringModule = ({recurringTemplates,setRecurringTemplates,clients,invoices,setInvoices,settings,addAudit,currentUser}) => {
  const [drawer,setDrawer]=useState(false);
  const [form,setForm]=useState({});
  const [editing,setEditing]=useState(null);
  const [delId,setDelId]=useState(null);
  const [genMsg,setGenMsg]=useState(null);

  const fc=(k,v)=>setForm(f=>({...f,[k]:v}));
  const cur=settings?.system?.currency||"USD";
  const thisMonth=new Date().toISOString().slice(0,7);
  const thisMonthLabel=new Date().toLocaleString("default",{month:"long",year:"numeric"});

  const blank={id:"",clientId:"",serviceType:"Monthly Package",location:"",amount:0,description:"",frequency:"monthly",dayOfMonth:1,active:true,lastGenerated:"",staffAssigned:"",notes:""};

  const openNew =()=>{setForm({...blank});setEditing(null);setDrawer(true);};
  const openEdit=(t)=>{setForm({...t});setEditing(t.id);setDrawer(true);};
  const save=()=>{
    if(!form.clientId||!form.amount) return;
    if(editing){
      setRecurringTemplates(ts=>ts.map(t=>t.id===editing?{...form}:t));
      addAudit("Updated","Recurring",editing,form.description||form.serviceType,"Template updated");
    } else {
      const id="REC-"+String(Math.max(0,...recurringTemplates.map(t=>parseInt(t.id.replace(/\D/g,""))||0))+1).padStart(3,"0");
      setRecurringTemplates(ts=>[...ts,{...form,id}]);
      addAudit("Created","Recurring",id,form.description||form.serviceType,"New recurring template");
    }
    setDrawer(false);setEditing(null);
  };
  const del=()=>{
    const t=recurringTemplates.find(x=>x.id===delId);
    setRecurringTemplates(ts=>ts.filter(t=>t.id!==delId));
    addAudit("Deleted","Recurring",delId,t?.description||delId,"Template deleted");
    setDelId(null);
  };

  // Generate invoice for this month for a template
  const generate=(tpl)=>{
    const alreadyExists=invoices.some(i=>i.recurringId===tpl.id&&i.date?.startsWith(thisMonth));
    if(alreadyExists){setGenMsg({type:"warn",text:`Invoice for ${thisMonthLabel} already exists for this template.`});setTimeout(()=>setGenMsg(null),4000);return;}
    const id=`INV-${String(Math.max(0,...invoices.map(i=>parseInt(i.id.replace(/\D/g,""))||0))+1).padStart(6,"0")}`;
    const day=String(tpl.dayOfMonth||1).padStart(2,"0");
    const date=`${thisMonth}-${day}`;
    const newInv={id,clientId:tpl.clientId,jobId:tpl.jobId||"",date,serviceType:tpl.serviceType,location:tpl.location,amount:tpl.amount,amountPaid:0,status:"Unpaid",paymentMethod:"",notes:tpl.notes||"",recurringId:tpl.id};
    setInvoices(is=>[newInv,...is]);
    setRecurringTemplates(ts=>ts.map(t=>t.id===tpl.id?{...t,lastGenerated:date}:t));
    addAudit("Created","Invoices",id,id+" (from recurring)","Auto-generated from recurring template "+tpl.id);
    setGenMsg({type:"ok",text:`✓ Invoice ${id} created for ${thisMonthLabel}`});
    setTimeout(()=>setGenMsg(null),4000);
  };

  // Generate ALL active templates for this month
  const generateAll=()=>{
    let count=0;
    const active=recurringTemplates.filter(t=>t.active);
    let newInvoices=[...invoices];
    const updatedTemplates=[...recurringTemplates];
    active.forEach(tpl=>{
      const alreadyExists=newInvoices.some(i=>i.recurringId===tpl.id&&i.date?.startsWith(thisMonth));
      if(alreadyExists) return;
      const id=`INV-${String(Math.max(0,...newInvoices.map(i=>parseInt(i.id.replace(/\D/g,""))||0))+1).padStart(6,"0")}`;
      const day=String(tpl.dayOfMonth||1).padStart(2,"0");
      const date=`${thisMonth}-${day}`;
      newInvoices=[{id,clientId:tpl.clientId,jobId:tpl.jobId||"",date,serviceType:tpl.serviceType,location:tpl.location,amount:tpl.amount,amountPaid:0,status:"Unpaid",paymentMethod:"",notes:tpl.notes||"",recurringId:tpl.id},...newInvoices];
      const ti=updatedTemplates.findIndex(t=>t.id===tpl.id);
      if(ti>=0) updatedTemplates[ti]={...updatedTemplates[ti],lastGenerated:date};
      addAudit("Created","Invoices",id,id+" (bulk recurring)","Generated from "+tpl.id);
      count++;
    });
    setInvoices(newInvoices);
    setRecurringTemplates(updatedTemplates);
    setGenMsg(count>0?{type:"ok",text:`✓ ${count} invoice${count>1?"s":""} generated for ${thisMonthLabel}`}:{type:"warn",text:`All invoices for ${thisMonthLabel} already exist.`});
    setTimeout(()=>setGenMsg(null),5000);
  };

  return (
    <div>
      {/* Header */}
      <div style={{background:"#fff",borderRadius:12,border:`1px solid ${C.border}`,padding:"16px 20px",marginBottom:16,display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:12}}>
        <div>
          <div style={{fontSize:15,fontWeight:700,color:C.text}}>🔁 Recurring Invoice Templates</div>
          <div style={{fontSize:12,color:C.muted,marginTop:2}}>Set up monthly contracts — generate invoices with one click each month</div>
        </div>
        <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"center"}}>
          <div style={{fontSize:12,color:C.muted,background:C.bg,padding:"6px 12px",borderRadius:8}}>
            Current month: <strong style={{color:C.text}}>{thisMonthLabel}</strong>
          </div>
          <Btn onClick={generateAll} variant="ghost">⚡ Generate All for {thisMonthLabel}</Btn>
          <Btn onClick={openNew}>+ New Template</Btn>
        </div>
      </div>

      {/* Toast message */}
      {genMsg&&<div style={{background:genMsg.type==="ok"?C.okBg:C.warnBg,color:genMsg.type==="ok"?C.ok:C.warn,padding:"10px 16px",borderRadius:10,marginBottom:14,fontSize:13,fontWeight:700,border:`1px solid ${genMsg.type==="ok"?C.ok:C.warn}`}}>
        {genMsg.text}
      </div>}

      {/* Stats */}
      <div style={{display:"flex",gap:10,marginBottom:14,flexWrap:"wrap"}}>
        <StatCard label="Total Templates" value={recurringTemplates.length}/>
        <StatCard label="Active" value={recurringTemplates.filter(t=>t.active).length} accent={C.ok}/>
        <StatCard label="Monthly Value" value={`${cur} ${recurringTemplates.filter(t=>t.active).reduce((a,t)=>a+t.amount,0).toFixed(2)}`} accent={C.accent}/>
        <StatCard label="Generated This Month" value={invoices.filter(i=>i.recurringId&&i.date?.startsWith(thisMonth)).length} accent={C.info}/>
      </div>

      {/* Templates */}
      {recurringTemplates.length===0
        ? <div style={{background:"#fff",borderRadius:12,border:`1px solid ${C.border}`,padding:48,textAlign:"center",color:C.muted,fontSize:13}}>
            <div style={{fontSize:32,marginBottom:12}}>🔁</div>
            <div style={{fontSize:14,fontWeight:700,marginBottom:6}}>No recurring templates yet</div>
            <div>Create templates for your monthly contracts to auto-generate invoices each month.</div>
          </div>
        : <div style={{display:"grid",gap:12}}>
            {recurringTemplates.map(tpl=>{
              const cl=clients.find(c=>c.id===tpl.clientId);
              const generatedThisMonth=invoices.some(i=>i.recurringId===tpl.id&&i.date?.startsWith(thisMonth));
              const totalGenerated=invoices.filter(i=>i.recurringId===tpl.id).length;
              return (
                <div key={tpl.id} style={{background:"#fff",borderRadius:12,border:`2px solid ${tpl.active?C.border:"#e2e8f0"}`,padding:"18px 22px",opacity:tpl.active?1:0.65,boxShadow:"0 1px 4px rgba(0,0,0,0.05)"}}>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:12}}>
                    <div style={{display:"flex",gap:14,alignItems:"flex-start",flex:1}}>
                      <div style={{width:44,height:44,borderRadius:12,background:tpl.active?C.accentLight:"#f0f0f0",display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0}}>🔁</div>
                      <div>
                        <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginBottom:4}}>
                          <span style={{fontSize:15,fontWeight:700,color:C.text}}>{cl?.name||"Unknown Client"}</span>
                          <Badge s={tpl.active?"Active":"Inactive"}/>
                          {generatedThisMonth&&<span style={{background:C.okBg,color:C.ok,padding:"2px 8px",borderRadius:20,fontSize:10,fontWeight:700}}>✓ Generated {thisMonthLabel}</span>}
                        </div>
                        <div style={{fontSize:12,color:C.muted,marginBottom:2}}>{tpl.description||tpl.serviceType} · {tpl.location}</div>
                        <div style={{fontSize:12,color:C.muted,display:"flex",gap:16,flexWrap:"wrap"}}>
                          <span>👤 {tpl.staffAssigned||"—"}</span>
                          <span>📅 Generates on day {tpl.dayOfMonth} of each month</span>
                          {tpl.lastGenerated&&<span>Last: {tpl.lastGenerated}</span>}
                          <span>📄 {totalGenerated} invoice{totalGenerated!==1?"s":""} generated total</span>
                        </div>
                      </div>
                    </div>
                    <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",flexShrink:0}}>
                      <div style={{fontSize:20,fontWeight:800,color:C.accent}}>{cur} {tpl.amount}</div>
                      <Btn onClick={()=>generate(tpl)} disabled={!tpl.active||generatedThisMonth} variant={generatedThisMonth?"secondary":"primary"} sm>
                        {generatedThisMonth?`✓ Done`:`⚡ Generate ${new Date().toLocaleString("default",{month:"short"})}`}
                      </Btn>
                      <Btn onClick={()=>openEdit(tpl)} variant="secondary" sm>Edit</Btn>
                      <Btn onClick={()=>setRecurringTemplates(ts=>ts.map(t=>t.id===tpl.id?{...t,active:!t.active}:t))} variant="secondary" sm>{tpl.active?"Pause":"Resume"}</Btn>
                      <Btn onClick={()=>setDelId(tpl.id)} variant="danger" sm>✕</Btn>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>}

      {/* Recent generated invoices */}
      {invoices.filter(i=>i.recurringId).length>0&&<div style={{background:"#fff",borderRadius:12,border:`1px solid ${C.border}`,padding:"16px 20px",marginTop:16}}>
        <div style={{fontSize:12,fontWeight:700,color:C.text,marginBottom:10}}>Recently Generated Invoices</div>
        <Tbl><thead><tr><TH>Invoice</TH><TH>Date</TH><TH>Client</TH><TH>Service</TH><TH>Amount</TH><TH>Status</TH></tr></thead>
          <tbody>{invoices.filter(i=>i.recurringId).slice(0,10).map(i=>{
            const cl=clients.find(c=>c.id===i.clientId);
            return <TRow key={i.id}><TD style={{color:C.accent,fontWeight:600,fontSize:11}}>{i.id}</TD><TD>{i.date}</TD><TD style={{fontWeight:700}}>{cl?.name||"—"}</TD><TD style={{color:C.muted,fontSize:11}}>{i.serviceType}</TD><TD style={{fontWeight:700}}>{cur} {i.amount}</TD><TD><Badge s={i.status}/></TD></TRow>;
          })}</tbody>
        </Tbl>
      </div>}

      <Drawer open={drawer} onClose={()=>{setDrawer(false);setEditing(null);}} title={editing?"Edit Template":"New Recurring Template"} width={500}>
        <Sel label="Client *" value={form.clientId} onChange={v=>fc("clientId",v)} options={[{value:"",label:"— Select —"},...clients.map(c=>({value:c.id,label:c.name}))]}/>
        <Inp label="Description" value={form.description} onChange={v=>fc("description",v)} placeholder="e.g. 3 visits/week 2hrs"/>
        <Sel label="Service Type" value={form.serviceType} onChange={v=>fc("serviceType",v)} options={["Monthly Package","One-time Cleaning","Deep Cleaning","Commercial Cleaning","Full Time Cleaner","Regular Cleaning"]}/>
        <Inp label="Location" value={form.location} onChange={v=>fc("location",v)}/>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          <Inp label="Monthly Amount (${cur})" value={form.amount} onChange={v=>fc("amount",parseFloat(v)||0)} type="number"/>
          <Inp label="Generate on Day" value={form.dayOfMonth} onChange={v=>fc("dayOfMonth",parseInt(v)||1)} type="number"/>
        </div>
        <Sel label="Assigned Staff" value={form.staffAssigned} onChange={v=>fc("staffAssigned",v)} options={["—","Mountaha","Nahed","Mona","Zouzou","Cherine","Joujou","Em Omar","Makka"]}/>
        <Textarea label="Notes" value={form.notes} onChange={v=>fc("notes",v)} rows={2}/>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,padding:"10px 14px",background:C.bg,borderRadius:8}}>
          <input type="checkbox" id="tplActive" checked={!!form.active} onChange={e=>fc("active",e.target.checked)} style={{cursor:"pointer",width:16,height:16}}/>
          <label htmlFor="tplActive" style={{fontSize:13,fontWeight:600,cursor:"pointer",color:C.text}}>Active — will generate invoices automatically</label>
        </div>
        <div style={{display:"flex",gap:8}}><Btn onClick={save}>Save Template</Btn><Btn onClick={()=>{setDrawer(false);setEditing(null);}} variant="secondary">Cancel</Btn></div>
      </Drawer>
      <ConfirmModal open={!!delId} onClose={()=>setDelId(null)} onConfirm={del} message="Delete this recurring template? Existing invoices will remain."/>
    </div>
  );
};

// ─── APPROVALS MODULE (5B) ────────────────────────────────────────────────────
const ApprovalsModule = ({approvals,setApprovals,invoices,setInvoices,quotations,setQuotations,clients,currentUser,addAudit}) => {
  const [tab,setTab]=useState("pending");
  const [comment,setComment]=useState({});

  const pending   = approvals.filter(a=>a.status==="Pending");
  const approved  = approvals.filter(a=>a.status==="Approved");
  const rejected  = approvals.filter(a=>a.status==="Rejected");
  const shown     = tab==="pending"?pending:tab==="approved"?approved:rejected;

  const canApprove = currentUser.role==="Admin";

  const decide=(approval,decision)=>{
    const note=comment[approval.id]||"";
    const ts=new Date().toISOString();
    // Update approval record
    setApprovals(as=>as.map(a=>a.id===approval.id?{...a,status:decision,decidedBy:currentUser.name,decidedAt:ts,comment:note}:a));
    // Update the linked document
    if(approval.docType==="invoice"){
      setInvoices(is=>is.map(i=>i.id===approval.docId?{...i,approvalStatus:decision}:i));
    } else if(approval.docType==="quotation"){
      setQuotations(qs=>qs.map(q=>q.id===approval.docId?{...q,approvalStatus:decision}:q));
    }
    addAudit(decision,"Approvals",approval.id,`${approval.docType} ${approval.docId}`,`${decision} by ${currentUser.name}${note?" — "+note:""}`);
    setComment(c=>({...c,[approval.id]:""}));
  };

  const getDocInfo=(a)=>{
    if(a.docType==="invoice"){
      const inv=invoices.find(i=>i.id===a.docId);
      const cl=clients.find(c=>c.id===inv?.clientId);
      return {inv,cl,amount:inv?.amount,label:`Invoice ${a.docId}`};
    } else {
      const qt=quotations.find(q=>q.id===a.docId);
      const cl=clients.find(c=>c.id===qt?.clientId);
      return {qt,cl,amount:qt?.price,label:`Quotation ${a.docId}`};
    }
  };

  return (
    <div>
      {/* Stats */}
      <div style={{display:"flex",gap:10,marginBottom:14,flexWrap:"wrap"}}>
        <StatCard label="Pending" value={pending.length} accent={pending.length>0?C.warn:C.ok}/>
        <StatCard label="Approved" value={approved.length} accent={C.ok}/>
        <StatCard label="Rejected" value={rejected.length} accent={C.err}/>
        <StatCard label="Total Requests" value={approvals.length}/>
      </div>

      {!canApprove&&pending.length>0&&<div style={{background:C.infoBg,color:C.info,padding:"10px 16px",borderRadius:10,marginBottom:14,fontSize:12,fontWeight:600}}>
        ℹ️ {pending.length} approval request{pending.length>1?"s":""} awaiting Admin decision.
      </div>}

      {/* Tabs */}
      <div style={{display:"flex",gap:4,marginBottom:16,background:"#fff",borderRadius:12,padding:5,border:`1px solid ${C.border}`,width:"fit-content"}}>
        {[{k:"pending",l:`⏳ Pending (${pending.length})`},{k:"approved",l:`✅ Approved (${approved.length})`},{k:"rejected",l:`❌ Rejected (${rejected.length})`}].map(({k,l})=>(
          <button key={k} onClick={()=>setTab(k)} style={{padding:"7px 16px",borderRadius:8,fontSize:12,fontWeight:600,cursor:"pointer",border:"none",background:tab===k?C.accent:"transparent",color:tab===k?"#1a1200":C.muted,transition:"all 0.15s"}}>{l}</button>
        ))}
      </div>

      {shown.length===0
        ? <div style={{background:"#fff",borderRadius:12,border:`1px solid ${C.border}`,padding:"48px 0",textAlign:"center",color:C.muted,fontSize:13}}>
            <div style={{fontSize:28,marginBottom:10}}>{tab==="pending"?"⏳":tab==="approved"?"✅":"❌"}</div>
            No {tab} approvals.
          </div>
        : <div style={{display:"grid",gap:12}}>
            {shown.map(a=>{
              const {cl,amount,label}=getDocInfo(a);
              const isPending=a.status==="Pending";
              return (
                <div key={a.id} style={{background:"#fff",borderRadius:12,border:`2px solid ${isPending?C.warn:a.status==="Approved"?C.ok:C.err}`,padding:"18px 22px",boxShadow:"0 1px 4px rgba(0,0,0,0.05)"}}>
                  <div style={{display:"flex",justifyContent:"space-between",flexWrap:"wrap",gap:12}}>
                    <div>
                      <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:6,flexWrap:"wrap"}}>
                        <span style={{fontSize:14,fontWeight:700,color:C.text}}>{label}</span>
                        <Badge s={a.status==="Pending"?"Pending":a.status==="Approved"?"Accepted":"Rejected"}/>
                        <span style={{background:C.infoBg,color:C.info,padding:"2px 8px",borderRadius:20,fontSize:10,fontWeight:600,textTransform:"capitalize"}}>{a.docType}</span>
                      </div>
                      <div style={{fontSize:12,color:C.muted,display:"flex",gap:16,flexWrap:"wrap"}}>
                        <span>👤 Client: <strong style={{color:C.text}}>{cl?.name||"—"}</strong></span>
                        {amount&&<span>💰 Amount: <strong style={{color:C.ok}}>$ {amount}</strong></span>}
                        <span>📅 Submitted: {a.submittedAt?.slice(0,10)} by {a.submittedBy}</span>
                        {a.decidedAt&&<span>✓ Decided: {a.decidedAt.slice(0,10)} by {a.decidedBy}</span>}
                      </div>
                      {a.requestNote&&<div style={{marginTop:8,padding:"6px 10px",background:C.bg,borderRadius:6,fontSize:11,color:C.muted}}><strong>Request note:</strong> {a.requestNote}</div>}
                      {a.comment&&<div style={{marginTop:6,padding:"6px 10px",background:a.status==="Approved"?C.okBg:C.errBg,borderRadius:6,fontSize:11,color:a.status==="Approved"?C.ok:C.err}}><strong>Decision note:</strong> {a.comment}</div>}
                    </div>

                    {/* Approve / Reject buttons (Admin only, pending only) */}
                    {canApprove&&isPending&&<div style={{display:"flex",flexDirection:"column",gap:8,minWidth:220}}>
                      <input value={comment[a.id]||""} onChange={e=>setComment(c=>({...c,[a.id]:e.target.value}))} placeholder="Optional comment…"
                        style={{padding:"7px 10px",border:`1px solid ${C.border}`,borderRadius:8,fontSize:12,outline:"none",fontFamily:"inherit"}}/>
                      <div style={{display:"flex",gap:8}}>
                        <button onClick={()=>decide(a,"Approved")} style={{flex:1,background:C.okBg,color:C.ok,border:`2px solid ${C.ok}`,borderRadius:8,padding:"8px 0",fontSize:13,fontWeight:700,cursor:"pointer"}}>✅ Approve</button>
                        <button onClick={()=>decide(a,"Rejected")} style={{flex:1,background:C.errBg,color:C.err,border:`2px solid ${C.err}`,borderRadius:8,padding:"8px 0",fontSize:13,fontWeight:700,cursor:"pointer"}}>❌ Reject</button>
                      </div>
                    </div>}
                  </div>
                </div>
              );
            })}
          </div>}
    </div>
  );
};

// ─── APPROVAL REQUEST BUTTON (reusable) ──────────────────────────────────────
const RequestApprovalBtn = ({docId,docType,amount,currentUser,approvals,setApprovals,addAudit}) => {
  const [note,setNote]=useState("");
  const [open,setOpen]=useState(false);

  const existing=approvals.find(a=>a.docId===docId&&a.status==="Pending");
  const approved=approvals.find(a=>a.docId===docId&&a.status==="Approved");
  const rejected=approvals.find(a=>a.docId===docId&&a.status==="Rejected");

  const submit=()=>{
    const id=`APR-${Date.now()}`;
    setApprovals(as=>[...as,{id,docId,docType,status:"Pending",submittedBy:currentUser.name,submittedAt:new Date().toISOString(),requestNote:note,decidedBy:null,decidedAt:null,comment:""}]);
    addAudit("Submitted","Approvals",id,`${docType} ${docId}`,"Approval requested by "+currentUser.name);
    setOpen(false);setNote("");
    showToast("✓ Approval request submitted to Admin");
  };

  if(approved) return <span style={{background:C.okBg,color:C.ok,padding:"3px 10px",borderRadius:20,fontSize:11,fontWeight:700}}>✅ Approved</span>;
  if(rejected) return <span style={{background:C.errBg,color:C.err,padding:"3px 10px",borderRadius:20,fontSize:11,fontWeight:700}}>❌ Rejected</span>;
  if(existing) return <span style={{background:C.warnBg,color:C.warn,padding:"3px 10px",borderRadius:20,fontSize:11,fontWeight:700}}>⏳ Awaiting Approval</span>;

  return (
    <>
      <Btn onClick={()=>setOpen(true)} variant="ghost" sm>📋 Request Approval</Btn>
      {open&&<div style={{position:"fixed",inset:0,zIndex:1200,display:"flex",alignItems:"center",justifyContent:"center"}}>
        <div style={{position:"absolute",inset:0,background:"rgba(0,0,0,0.45)"}} onClick={()=>setOpen(false)}/>
        <div style={{position:"relative",background:"#fff",borderRadius:14,padding:24,maxWidth:380,width:"90%",boxShadow:"0 20px 60px rgba(0,0,0,0.3)"}}>
          <div style={{fontSize:14,fontWeight:700,marginBottom:4}}>Request Approval</div>
          <div style={{fontSize:12,color:C.muted,marginBottom:14}}>{docType} {docId}{amount?` — $${amount}`:""}</div>
          <textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Optional note for approver…" rows={3}
            style={{width:"100%",padding:"8px 10px",border:`1px solid ${C.border}`,borderRadius:8,fontSize:12,outline:"none",boxSizing:"border-box",fontFamily:"inherit",resize:"vertical",marginBottom:14}}/>
          <div style={{display:"flex",gap:8}}><Btn onClick={submit}>Submit Request</Btn><Btn onClick={()=>setOpen(false)} variant="secondary">Cancel</Btn></div>
        </div>
      </div>}
    </>
  );
};
